-- ============================================================================
-- 0006 — ASSIGNMENTS, SUBMISSIONS, SCHEDULED REMINDERS
-- Reminders are generated by DB triggers from community settings and
-- delivered by the pg_cron processor every 5 minutes. Delivery is idempotent
-- (unique delivery-log rows + notification dedupe keys).
-- ============================================================================

create table public.assignments (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text,
  instructions text,
  topics text[] not null default '{}',
  difficulty text default 'mixed' check (difficulty in ('easy', 'medium', 'hard', 'mixed')),
  starts_at timestamptz,
  due_at timestamptz,
  max_score numeric,
  week_id uuid references public.training_weeks (id) on delete set null,
  sheet_id uuid references public.problem_sheets (id) on delete set null,
  problem_url text,
  submission_requirements text,
  attachments jsonb not null default '[]',   -- [{name, url}]
  mode text not null default 'individual' check (mode in ('individual', 'team')),
  reminder_target text not null default 'all' check (reminder_target in ('all', 'leader')),
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (due_at is null or starts_at is null or starts_at <= due_at)
);

create index idx_assignments_status on public.assignments (status);
create index idx_assignments_due on public.assignments (due_at);

create trigger trg_assignments_updated_at
  before update on public.assignments
  for each row execute function public.set_updated_at();

create table public.assignment_submissions (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.assignments (id) on delete cascade,
  student_id uuid not null references public.profiles (id),
  team_id uuid references public.teams (id),
  content_url text,
  notes text,
  status text not null default 'submitted'
    check (status in ('submitted', 'late', 'under_review', 'accepted', 'needs_improvement')),
  score numeric,
  feedback text,
  reviewed_by uuid references public.profiles (id),
  reviewed_at timestamptz,
  submitted_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index uq_submissions_individual on public.assignment_submissions (assignment_id, student_id)
  where team_id is null;
create unique index uq_submissions_team on public.assignment_submissions (assignment_id, team_id)
  where team_id is not null;
create index idx_submissions_assignment on public.assignment_submissions (assignment_id);

create trigger trg_submissions_updated_at
  before update on public.assignment_submissions
  for each row execute function public.set_updated_at();

create table public.scheduled_reminders (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null references public.assignments (id) on delete cascade,
  kind text not null check (kind in ('advance', 'deadline')),
  offset_days int not null,
  remind_at timestamptz not null,
  status text not null default 'scheduled'
    check (status in ('scheduled', 'processing', 'sent', 'cancelled', 'failed'))
);

create unique index uq_reminders_scheduled on public.scheduled_reminders (assignment_id, offset_days)
  where status = 'scheduled';
create index idx_reminders_due on public.scheduled_reminders (status, remind_at);

create table public.reminder_delivery_logs (
  id bigint generated always as identity primary key,
  reminder_id uuid not null references public.scheduled_reminders (id) on delete cascade,
  recipient_id uuid not null references public.profiles (id) on delete cascade,
  channel text not null default 'in_app' check (channel in ('in_app', 'email')),
  status text not null default 'sent' check (status in ('sent', 'failed')),
  error text,
  delivered_at timestamptz not null default now(),
  unique (reminder_id, recipient_id, channel)
);

-- ----------------------------------------------------------------------------
-- Reminder generation: (re)generate on publish / deadline change.
-- ----------------------------------------------------------------------------
create or replace function public.regenerate_assignment_reminders()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  v_offsets int[];
  v_send_deadline boolean;
  o int;
begin
  -- cancel pending when unpublished, archived, or no deadline
  if new.status <> 'published' or new.due_at is null then
    update public.scheduled_reminders set status = 'cancelled'
    where assignment_id = new.id and status = 'scheduled';
    return new;
  end if;

  select reminder_offsets_days, send_deadline_reminder
  into v_offsets, v_send_deadline
  from public.community_settings where id = 1;
  v_offsets := coalesce(v_offsets, array[7,3,1]);
  v_send_deadline := coalesce(v_send_deadline, true);

  update public.scheduled_reminders set status = 'cancelled'
  where assignment_id = new.id and status = 'scheduled';

  foreach o in array v_offsets loop
    if new.due_at - (o || ' days')::interval > now() then
      insert into public.scheduled_reminders (assignment_id, kind, offset_days, remind_at)
      values (new.id, 'advance', o, new.due_at - (o || ' days')::interval);
    end if;
  end loop;

  if v_send_deadline and new.due_at > now() then
    insert into public.scheduled_reminders (assignment_id, kind, offset_days, remind_at)
    values (new.id, 'deadline', 0, new.due_at);
  end if;

  return new;
end;
$$;

create trigger trg_assignments_reminders
  after insert or update of due_at, status on public.assignments
  for each row execute function public.regenerate_assignment_reminders();

-- ----------------------------------------------------------------------------
-- Reminder delivery (cron every 5 min)
-- ----------------------------------------------------------------------------
create or replace function public.process_due_reminders()
returns void
language plpgsql
security definer set search_path = public
as $$
declare
  r record;
  a public.assignments%rowtype;
  v_recipient uuid;
  v_target text;
  v_team uuid;
  v_title text;
  v_body text;
  v_inserted boolean;
begin
  if not pg_try_advisory_lock(hashtext('icpc_reminders')) then
    return;
  end if;

  create temp table if not exists tmp_reminder_recipients (user_id uuid primary key) on commit drop;

  for r in
    select * from public.scheduled_reminders
    where status = 'scheduled' and remind_at <= now()
    order by remind_at
    limit 100
    for update skip locked
  loop
    select * into a from public.assignments where id = r.assignment_id;
    if a.id is null then
      update public.scheduled_reminders set status = 'cancelled' where id = r.id;
      continue;
    end if;

    update public.scheduled_reminders set status = 'processing' where id = r.id;
    v_target := a.reminder_target;
    delete from tmp_reminder_recipients;

    if a.mode = 'individual' then
      insert into tmp_reminder_recipients
      select p.id from public.profiles p
      where p.status = 'active' and p.role = 'student';
    elsif v_target = 'leader' then
      insert into tmp_reminder_recipients
      select distinct t.leader_id from public.teams t
      where t.status in ('complete', 'active') and t.leader_id is not null;
    else
      insert into tmp_reminder_recipients
      select tm.student_id
      from public.team_members tm
      join public.teams t on t.id = tm.team_id
      where tm.status = 'active' and t.status in ('complete', 'active');
    end if;

    v_title := case when r.kind = 'deadline'
                    then 'Assignment due now'
                    else 'Assignment deadline approaching' end;
    v_body := case when r.kind = 'deadline'
                   then '"' || a.title || '" is due now.'
                   else '"' || a.title || '" is due '
                        || to_char(a.due_at, 'YYYY-MM-DD HH24:MI') || ' (UTC).' end;

    for v_recipient in select user_id from tmp_reminder_recipients loop
      -- skip students who already submitted (own or their team's submission)
      select tm.team_id into v_team from public.team_members tm
      where tm.student_id = v_recipient and tm.status = 'active' limit 1;

      if exists (
        select 1 from public.assignment_submissions s
        where s.assignment_id = a.id
          and (s.student_id = v_recipient or (v_team is not null and s.team_id = v_team))
          and s.status not in ('needs_improvement')
      ) then
        continue;
      end if;

      insert into public.reminder_delivery_logs (reminder_id, recipient_id, channel, status)
      values (r.id, v_recipient, 'in_app', 'sent')
      on conflict (reminder_id, recipient_id, channel) do nothing;

      get diagnostics v_inserted = ROW_COUNT;
      if v_inserted > 0 then
        perform public.notify(v_recipient, 'assignment_reminder', v_title, v_body,
                              '/assignments/' || a.id::text, 'assignment', a.id::text,
                              'rem-' || r.id::text || '-' || v_recipient::text);
      end if;
    end loop;

    update public.scheduled_reminders set status = 'sent' where id = r.id;
  end loop;

  drop table if exists tmp_reminder_recipients;
  perform pg_advisory_unlock(hashtext('icpc_reminders'));
end;
$$;

-- ----------------------------------------------------------------------------
-- Submission RPCs
-- ----------------------------------------------------------------------------
create or replace function public.submit_assignment(
  p_assignment_id uuid,
  p_content_url text,
  p_notes text default null
)
returns uuid
language plpgsql
security definer set search_path = public
as $$
declare
  a public.assignments%rowtype;
  v_user uuid := auth.uid();
  v_team uuid;
  v_status text;
  v_id uuid;
begin
  if not public.is_active_user() then
    raise exception 'Account is not active';
  end if;

  select * into a from public.assignments where id = p_assignment_id;
  if a.id is null or a.status <> 'published' then
    raise exception 'Assignment not found';
  end if;

  if a.mode = 'team' then
    select tm.team_id into v_team from public.team_members tm
    where tm.student_id = v_user and tm.status = 'active' limit 1;
    if v_team is null then
      raise exception 'This is a team assignment — join a team first';
    end if;
  end if;

  v_status := case when a.due_at is not null and now() > a.due_at then 'late' else 'submitted' end;

  insert into public.assignment_submissions (assignment_id, student_id, team_id, content_url, notes, status)
  values (a.id, v_user, v_team, p_content_url, p_notes, v_status)
  on conflict do nothing
  returning id into v_id;

  if v_id is null then
    if a.mode = 'team' then
      update public.assignment_submissions
      set content_url = p_content_url, notes = p_notes, submitted_at = now(),
          status = case when a.due_at is not null and now() > a.due_at then 'late' else 'submitted' end,
          student_id = v_user
      where assignment_id = a.id and team_id = v_team
      returning id into v_id;
    else
      update public.assignment_submissions
      set content_url = p_content_url, notes = p_notes, submitted_at = now(),
          status = case when a.due_at is not null and now() > a.due_at then 'late' else 'submitted' end
      where assignment_id = a.id and student_id = v_user and team_id is null
      returning id into v_id;
    end if;
  end if;

  return v_id;
end;
$$;

create or replace function public.review_submission(
  p_submission_id uuid,
  p_status text,
  p_score numeric default null,
  p_feedback text default null
)
returns void
language plpgsql
security definer set search_path = public
as $$
declare
  s public.assignment_submissions%rowtype;
begin
  if not public.is_admin() then
    raise exception 'Administrator access required';
  end if;
  if p_status not in ('under_review', 'accepted', 'needs_improvement') then
    raise exception 'Invalid review status';
  end if;

  select * into s from public.assignment_submissions where id = p_submission_id;
  if s.id is null then
    raise exception 'Submission not found';
  end if;

  update public.assignment_submissions
  set status = p_status, score = p_score, feedback = p_feedback,
      reviewed_by = auth.uid(), reviewed_at = now()
  where id = p_submission_id;

  perform public.notify(s.student_id, 'assignment', 'Submission reviewed',
    'Your submission for the assignment was reviewed: ' || replace(p_status, '_', ' ') || '.',
    '/assignments/' || s.assignment_id::text, 'assignment_submission', s.id::text);
  perform public.audit_log('assignment.review', 'assignment_submission', s.id::text,
    jsonb_build_object('status', p_status, 'score', p_score));
end;
$$;

-- ----------------------------------------------------------------------------
-- RLS
-- ----------------------------------------------------------------------------
alter table public.assignments enable row level security;

create policy "Published assignments visible; admins all"
  on public.assignments for select to authenticated
  using (status = 'published' or public.is_admin());

create policy "Admins manage assignments"
  on public.assignments for insert to authenticated
  with check (public.is_admin());

create policy "Admins update assignments"
  on public.assignments for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

create policy "Admins delete assignments"
  on public.assignments for delete to authenticated
  using (public.is_admin());

alter table public.assignment_submissions enable row level security;

create policy "Own or team submissions visible; admins all"
  on public.assignment_submissions for select to authenticated
  using (
    public.is_admin()
    or student_id = auth.uid()
    or (
      team_id is not null
      and exists (
        select 1 from public.team_members tm
        where tm.team_id = assignment_submissions.team_id
          and tm.student_id = auth.uid() and tm.status = 'active'
      )
    )
  );

-- Reminder tables: admin-only visibility; writes happen in trusted code only.
alter table public.scheduled_reminders enable row level security;

create policy "Admins read scheduled reminders"
  on public.scheduled_reminders for select to authenticated
  using (public.is_admin());

alter table public.reminder_delivery_logs enable row level security;

create policy "Admins read delivery logs"
  on public.reminder_delivery_logs for select to authenticated
  using (public.is_admin());
